function demoMain(idx,label){
  var cases=[["valid token","ALLOW"],["expired token","DENY"],["missing token","DENY"]];
  var c=cases[idx%cases.length];
  return "["+label+"] auth case '"+c[0]+"' => "+c[1]+" (expected "+c[1]+")";
}

